// Validate the aggregate response before formatting an email.
// Fail safely: invalid/error responses take the no-email branch.
const input = $input.first().json || {};
const volumes = input.volumes || {};
const isDate = typeof input.date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(input.date);
const isNumber = value => typeof value === 'number' && Number.isFinite(value) && value >= 0;
const valid = !input.error && input.timezone === 'UTC' && isDate
  && isNumber(volumes.alerts) && isNumber(volumes.incidents) && isNumber(volumes.feedback)
  && isNumber(input.false_positive_count) && isNumber(input.feedback_count)
  && typeof input.false_positive_rate === 'number'
  && Array.isArray(input.top_rules) && Array.isArray(input.tuning_suggestions);

if (!valid) {
  return { json: { _digest: { valid: false, reason: 'stats_endpoint_failed' } } };
}

return { json: { ...input, _digest: { valid: true } } };

// Deterministic plain-text and HTML digest from aggregate fields only.
const stats = $input.first().json;
const escapeHtml = value => String(value)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;').replace(/'/g, '&#39;');
const fixed = value => Number(value).toFixed(4);
const lexical = (left, right) => String(left) < String(right) ? -1 : (String(left) > String(right) ? 1 : 0);
const topRules = [...stats.top_rules]
  .sort((a, b) => Number(b.count) - Number(a.count) || lexical(a.rule_id, b.rule_id))
  .map((item, index) => `${index + 1}. ${item.rule_id} — ${item.count}`);
const suggestions = [...stats.tuning_suggestions]
  .sort((a, b) => Number(b.false_positive_count) - Number(a.false_positive_count)
    || lexical(a.rule_id, b.rule_id)
    || lexical(a.agent_id, b.agent_id))
  .map(item => `${item.rule_id} / agent ${item.agent_id} — ${item.false_positive_count} false positives`);
const topText = topRules.length ? topRules.join('\n') : 'None';
const suggestionText = suggestions.length ? suggestions.join('\n') : 'None';
const bodyText = [
  `SOC daily digest — ${stats.date} (${stats.timezone})`,
  '',
  'Volumes',
  `Alerts: ${stats.volumes.alerts}`,
  `Incidents: ${stats.volumes.incidents}`,
  `Feedback: ${stats.volumes.feedback}`,
  '',
  `False-positive rate: ${fixed(stats.false_positive_rate)} (${stats.false_positive_count} / ${stats.feedback_count})`,
  '',
  'Top rules',
  topText,
  '',
  'Tuning suggestions — human approval required; no rule changes were made',
  suggestionText
].join('\n');
const topHtml = topRules.map(item => `<li>${escapeHtml(item)}</li>`).join('') || '<li>None</li>';
const suggestionHtml = suggestions.map(item => `<li>${escapeHtml(item)}</li>`).join('') || '<li>None</li>';
const html = `<h2>SOC daily digest — ${escapeHtml(stats.date)} (${escapeHtml(stats.timezone)})</h2>`
  + `<h3>Volumes</h3><ul><li>Alerts: ${stats.volumes.alerts}</li><li>Incidents: ${stats.volumes.incidents}</li><li>Feedback: ${stats.volumes.feedback}</li></ul>`
  + `<p>False-positive rate: ${fixed(stats.false_positive_rate)} (${stats.false_positive_count} / ${stats.feedback_count})</p>`
  + `<h3>Top rules</h3><ol>${topHtml}</ol>`
  + `<h3>Tuning suggestions — human approval required; no rule changes were made</h3><ul>${suggestionHtml}</ul>`;
return { json: { _digest: { valid: true, subject: `[SOC] Daily digest — ${stats.date}`, bodyText, html } } };
